            ["GET", "/api/dishes/:dishId/audio", "Audio món theo ngôn ngữ", "language", "audioUrl, duration, title", "Công khai"],
            ["GET", "/api/culinary-places/:placeId/translation", "Bản dịch địa điểm", "language", "bản dịch hoặc 403 nếu thiếu", "Công khai"],
            ["GET", "/api/dishes/:dishId/translation", "Bản dịch món", "language", "bản dịch hoặc 403 nếu thiếu", "Công khai"],
            ["GET", "/api/translations/:id/audio", "Bản ghi audio của bản dịch", "—", "audio", "ADMIN, STAFF"],
