            ["GET", "/api/dishes/:id/qr", "Đọc QR món", "—", "qr_code", "Công khai"],
            ["POST", "/api/dishes/:id/qr", "Tạo QR món", "base_url? / origin_hint", "qr_code", "ADMIN, STAFF"],
            ["GET", "/api/dashboard/statistics", "Số liệu tổng hợp", "—", "overview, charts", "ADMIN, STAFF"],
            ["GET", "/api/favorites", "Địa điểm yêu thích", "session_id, lang", "mảng địa điểm", "Công khai"],
            ["POST", "/api/favorites", "Thêm yêu thích", "session_id, culinary_place_id", "{ added: true }", "Công khai"],
