            ["POST", "/api/guest-sessions/free-language", "Chọn ngôn ngữ miễn phí", "language_id", "entitlement hoặc 409", "Cookie phiên"],
            ["GET", "/api/guest-sessions/language-packages", "Danh sách gói", "—", "packages, languages", "Công khai"],
